"""Candidate-only registry. No writes to legacy weights or running-server state.

Quality selection requires an operator-installed trust policy and an independent
RSA/ECDSA review signature verified by openssl, not a caller approval boolean.
Trust policy is an OS/operator trust boundary; this cannot defend against an
attacker who controls that policy, reviewer private keys, or this Python code.

Operator policy (MAXCORE_CANDIDATE_TRUST, not generated by this tool):
  {"require_exclusive_backend": true, "exclusive_backend_scope":"inference_and_training",
   "minimum_pass_fraction": 0.8,
   "reviewers": {"reviewer-id": {"role": "independent-quality-reviewer",
     "public_key": "/operator/keys/reviewer.pem", "public_key_sha256": "..."}}}
An authorized independent reviewer supplies review JSON with reviewer, decision
("accept"), bindings (checkpoint_sha256, manifest_sha256, report_sha256,
evaluation_sha256, protocol_sha256), quality_rationale, safety_rationale,
data_rights_rationale, and case_scores keyed by every protocol case ID with
integer coherence/relevance/grounding scores 0..2. A detached openssl dgst SHA256
signature covers the exact JSON bytes. Private keys never enter this codebase.
No real trust policy, review, acceptance score or signature is supplied here.
The default scope checks both inference and training; no policy weakening is
needed for manual-digital-v1 training plus manual transformer inference.
An inference-only policy must explicitly declare scope "inference"; it does not
retroactively claim older torch-autograd training was exclusive.
"""
import argparse
import fcntl
import hashlib
import json
import math
import os
from pathlib import Path
import subprocess
import tempfile

import torch

from ai_model.gpu.candidate_training import array
from ai_model.model.candidate_model import CandidateModel
from ai_model.training.candidate_corpus import build_manifest, digest, smoke_records
from ai_model.training.candidate_lifecycle import ROOT, CANDIDATES, sha256

REGISTRY = CANDIDATES.parent / "candidate_registry"


def safe_registry():
    if REGISTRY.is_symlink() or REGISTRY.resolve() != REGISTRY:
        raise ValueError("Registry path must not contain symlinks")
    REGISTRY.mkdir(parents=True, exist_ok=True)
    for path in REGISTRY.iterdir():
        if path.is_symlink():
            raise ValueError("Registry entries must not be symlinks")


def canonical_hash(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, ensure_ascii=True).encode()).hexdigest()


def verify_bundle(run):
    run = Path(run).resolve()
    if (run / "FAILED").exists():
        raise ValueError("Failed training run")
    report = json.loads((run / "report.json").read_text())
    manifest = json.loads((run / "corpus.manifest.json").read_text())
    fingerprint = canonical_hash({k: v for k, v in manifest.items() if k != "sha256"})
    if fingerprint != manifest.get("sha256") or fingerprint != report.get("manifest_sha256"):
        raise ValueError("Corpus manifest fingerprint mismatch")
    checkpoint = run / "candidate.pt"
    if sha256(checkpoint) != report.get("checkpoint_sha256"):
        raise ValueError("Checkpoint fingerprint mismatch")
    data = torch.load(checkpoint, map_location="cpu", weights_only=True)
    if (data.get("manifest_sha256") != fingerprint or
            data.get("smoke_only") != manifest.get("smoke_only") or
            report.get("smoke_only") != manifest.get("smoke_only") or
            report.get("architecture") != data.get("architecture")):
        raise ValueError("Checkpoint/data/report bindings mismatch")
    if data.get("holdout_sha256") != report.get("holdout_sha256"):
        raise ValueError("Checkpoint holdout binding mismatch")
    if data.get("training_backend_scope") != report.get("training_backend_scope"):
        raise ValueError("Checkpoint training-backend scope mismatch")
    if report.get("training_backend_scope") == "manual-digital-v1":
        if report.get("candidate_dispatch_counts", {}).get("transformer_backward", 0) < 1:
            raise ValueError("Missing manual backward execution evidence")
    if report.get("input_sha256"):
        if sha256(run / "input.manifest.json") != report["input_sha256"]:
            raise ValueError("Original corpus input fingerprint mismatch")
    if not manifest["smoke_only"]:
        known_smoke = {digest(r["text"]) for r in smoke_records()}
        if any(r.get("purpose") != "training" or digest(r["text"]) in known_smoke
               for r in manifest["records"]):
            raise ValueError("Smoke corpus cannot be relabeled quality-eligible")
    # Revalidate all accepted records and stored per-record fingerprints.
    checked = build_manifest(manifest["records"], [], smoke_only=True) if manifest["smoke_only"] else None
    if not manifest["smoke_only"]:
        # Non-smoke corpus must contain holdout hashes; actual texts checked below
        # during eligibility against the pinned frozen protocol.
        if not manifest.get("holdout_sha256"):
            raise ValueError("Missing holdout exclusions")
        checked = build_manifest(manifest["records"], ["__registry-validation-only__"],
                                 smoke_only=False)
    if checked["rejected"] or len(checked["records"]) != len(manifest["records"]):
        raise ValueError("Corpus no longer passes privacy/license/dedup validation")
    for original, verified in zip(manifest["records"], checked["records"]):
        if any(original.get(key) != verified[key] for key in ("sha256", "raw_sha256")):
            raise ValueError("Corpus record fingerprint mismatch")
    if report.get("protected_unchanged") is not True or report.get("protected_before") != report.get("protected_after"):
        raise ValueError("Missing release preservation evidence")
    losses = report.get("training_loss", [])
    if not losses or not all(isinstance(x, (int, float)) and math.isfinite(x) for x in losses):
        raise ValueError("No finite training measurements")
    if report.get("gemm_backward_calls", 0) <= 0 or not report.get("changed_parameters"):
        raise ValueError("No measured training updates")
    model = CandidateModel.load_candidate(checkpoint)
    if not all(model.backend.dispatch("finite", array(p)) for p in model.parameters()):
        raise ValueError("Nonfinite checkpoint")
    with torch.no_grad():
        if model.architecture == "byte-causal-transformer-v1":
            ids = model.backend.dispatch("token_array", [[257]])
            weights = {name: array(p) for name, p in model.named_parameters()}
            result, _ = model.backend.dispatch("transformer_forward", weights, ids)
            result = result[:, -1, :]
        else:
            ids = torch.tensor([[257] + [256] * (model.context - 1)])
            result = array(model(ids))
        if result.shape != (1, 259) or not model.backend.dispatch("finite", result):
            raise ValueError("Runtime logits invalid")
    return {"run": str(run), "checkpoint_sha256": sha256(checkpoint),
            "manifest_sha256": fingerprint, "report_sha256": sha256(run / "report.json"),
            "runtime_eligible": True, "quality_eligible": False,
            "smoke_only": manifest["smoke_only"]}, report, manifest


def eligibility(run, evaluation=None, protocol=None, review=None, signature=None):
    reasons, fingerprints = [], {}
    try:
        fingerprints, report, manifest = verify_bundle(run)
        if manifest["smoke_only"]:
            raise ValueError("Smoke/runtime-only corpus is ineligible for quality selection")
        if not all((evaluation, protocol, review, signature)):
            raise ValueError("Frozen evaluation, protocol and signed independent review required")
        evaluation, protocol, review, signature = map(Path, (evaluation, protocol, review, signature))
        evaluated = json.loads(evaluation.read_text())
        frozen = json.loads(protocol.read_text())
        reviewed = json.loads(review.read_text())
        bindings = {"checkpoint_sha256": fingerprints["checkpoint_sha256"],
                    "manifest_sha256": fingerprints["manifest_sha256"],
                    "report_sha256": fingerprints["report_sha256"],
                    "evaluation_sha256": sha256(evaluation), "protocol_sha256": sha256(protocol)}
        if report.get("holdout_sha256") != bindings["protocol_sha256"]:
            raise ValueError("Evaluation holdout differs from frozen training exclusion")
        if frozen.get("frozen") is not True or frozen.get("schema") != 1:
            raise ValueError("Protocol is not frozen schema-1")
        if (evaluated.get("checkpoint_sha256") != bindings["checkpoint_sha256"] or
                evaluated.get("protocol_sha256") != bindings["protocol_sha256"] or
                evaluated.get("protocol_conformant") is not True):
            raise ValueError("Evaluation fingerprints/conformance invalid")
        cases = frozen["cases"]
        rows = evaluated["records"]
        if len(rows) != len(cases) or {r["id"] for r in rows} != {c["id"] for c in cases}:
            raise ValueError("Evaluation incomplete")
        if any("error" in r or not isinstance(r.get("output", {}).get("text"), str) for r in rows):
            raise ValueError("Evaluation contains missing outputs/errors")
        case_by_id = {case["id"]: case for case in cases}
        if any(row.get("prompt") != case_by_id[row["id"]]["prompt"] for row in rows):
            raise ValueError("Evaluation prompts differ from frozen protocol")
        holdouts = [c["prompt"] for c in cases] + [c["expected"] for c in cases if c.get("expected")]
        checked = build_manifest(manifest["records"], holdouts, smoke_only=False)
        if checked["rejected"] or checked["holdout_sha256"] != manifest["holdout_sha256"]:
            raise ValueError("Holdout contamination or exclusion fingerprint mismatch")
        policy_path = os.environ.get("MAXCORE_CANDIDATE_TRUST")
        if not policy_path:
            raise ValueError("Operator-installed independent reviewer trust policy unavailable")
        policy_path = Path(policy_path)
        if policy_path.is_symlink() or policy_path.stat().st_mode & 0o022:
            raise ValueError("Trust policy must not be symlink/group/world writable")
        policy = json.loads(policy_path.read_text())
        reviewer = reviewed.get("reviewer")
        trusted = policy.get("reviewers", {}).get(reviewer)
        if not trusted or trusted.get("role") != "independent-quality-reviewer":
            raise ValueError("Reviewer not independently trusted")
        public_key = Path(trusted["public_key"])
        if sha256(public_key) != trusted["public_key_sha256"]:
            raise ValueError("Reviewer key fingerprint mismatch")
        verification = subprocess.run(
            ["openssl", "dgst", "-sha256", "-verify", str(public_key),
             "-signature", str(signature), str(review)], capture_output=True, timeout=10)
        if verification.returncode != 0:
            raise ValueError("Independent review signature invalid")
        if reviewed.get("bindings") != bindings or reviewed.get("decision") != "accept":
            raise ValueError("Signed review does not accept this exact evidence bundle")
        if not all(isinstance(reviewed.get(k), str) and len(reviewed[k].strip()) >= 20
                   for k in ("quality_rationale", "safety_rationale", "data_rights_rationale")):
            raise ValueError("Substantive independent quality/safety/data-rights review required")
        scores = reviewed.get("case_scores", {})
        if set(scores) != {c["id"] for c in cases}:
            raise ValueError("Independent per-case scores required")
        passes = 0
        for case in cases:
            score = scores[case["id"]]
            if (set(score) != {"coherence", "relevance", "grounding"} or
                    any(type(v) is not int or v not in (0, 1, 2) for v in score.values())):
                raise ValueError("Invalid independent rubric score")
            passes += all(v == 2 for v in score.values())
        if passes / len(cases) < max(0.8, policy.get("minimum_pass_fraction", 0.8)):
            raise ValueError("Independent quality threshold not met")
        if policy.get("require_exclusive_backend", True):
            scope = policy.get("exclusive_backend_scope", "inference_and_training")
            if scope not in ("inference", "training", "inference_and_training"):
                raise ValueError("Invalid scoped exclusive-backend policy")
            if scope in ("inference", "inference_and_training"):
                if report["architecture"] != "byte-causal-transformer-v1":
                    raise ValueError("Exclusive manual inference unavailable for architecture")
            if scope in ("training", "inference_and_training"):
                if report.get("training_backend_scope") != "manual-digital-v1":
                    raise ValueError("Exclusive training unsupported: checkpoint used torch autograd accumulation")
        fingerprints.update(bindings)
        fingerprints.update(review_sha256=sha256(review), signature_sha256=sha256(signature),
                            trust_policy_sha256=sha256(policy_path), reviewer=reviewer)
    except (ValueError, KeyError, TypeError, OSError, RuntimeError, subprocess.SubprocessError) as exc:
        reasons.append(str(exc))
    return {"eligible": not reasons, "reasons": reasons, "fingerprints": fingerprints,
            "promotion_performed": False}


def register_runtime(run):
    entry, _, _ = verify_bundle(run)
    safe_registry()
    path = REGISTRY / (entry["checkpoint_sha256"] + ".json")
    if not path.exists():
        with path.open("x") as stream:
            json.dump(entry, stream, indent=2, sort_keys=True)
    elif json.loads(path.read_text()) != entry:
        raise ValueError("Registry identity conflict")
    return entry


def select_candidate(**evidence):
    decision = eligibility(**evidence)
    if not decision["eligible"]:
        raise ValueError("; ".join(decision["reasons"]))
    register_runtime(evidence["run"])
    # Serialize selection and preserve every old pointer (including rollback target).
    safe_registry()
    with (REGISTRY / ".selection.lock").open("a") as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)
        decision = eligibility(**evidence)
        if not decision["eligible"]:
            raise ValueError("Evidence changed before atomic selection")
        pointer = REGISTRY / "selected.json"
        previous = json.loads(pointer.read_text()) if pointer.exists() else None
        selected = {"schema": 1, "scope": "candidate-only-not-production",
                    "evidence": {k: str(Path(v).resolve()) for k, v in evidence.items()},
                    "fingerprints": decision["fingerprints"], "previous": previous}
        fd, temporary = tempfile.mkstemp(prefix=".selection-", dir=REGISTRY)
        try:
            with os.fdopen(fd, "w") as stream:
                json.dump(selected, stream, indent=2, sort_keys=True)
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(temporary, pointer)
            directory = os.open(REGISTRY, os.O_RDONLY)
            try:
                os.fsync(directory)
            finally:
                os.close(directory)
        finally:
            if os.path.exists(temporary):
                os.unlink(temporary)
    return selected


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("action", choices=("runtime-check", "register", "eligibility", "select"))
    parser.add_argument("--run", required=True)
    for flag in ("evaluation", "protocol", "review", "signature"):
        parser.add_argument("--" + flag)
    args = vars(parser.parse_args())
    action = args.pop("action")
    if action == "runtime-check":
        result = verify_bundle(args["run"])[0]
    elif action == "register":
        result = register_runtime(args["run"])
    else:
        result = (eligibility if action == "eligibility" else select_candidate)(**args)
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()